package interfaces;
import estruturas.*;import javax.swing.*;import javax.swing.border.EmptyBorder;import java.awt.*;import java.util.*;
public class JanelaPrincipal extends JFrame{
 private final CardLayout cartas=new CardLayout();private final JPanel conteudo=new JPanel(cartas);private final Map<String,JButton> menuBotoes=new LinkedHashMap<>();
 private final PainelInicio inicio;private final PainelEstudantes estudantesUI;private final PainelDisciplinas disciplinasUI;private final PainelInscricoes inscricoesUI;private final PainelConsultas consultasUI;
 public JanelaPrincipal(){this(new TabelaHash(101),new ArvoreAVL());}
 private JanelaPrincipal(TabelaHash e,ArvoreAVL d){this(e,d,new GestaoInscricoes(e,d));}
 public JanelaPrincipal(TabelaHash e,ArvoreAVL d,GestaoInscricoes g){setTitle("Sistema de Gestão Académica");setSize(1280,790);setMinimumSize(new Dimension(1100,690));setLocationRelativeTo(null);setDefaultCloseOperation(EXIT_ON_CLOSE);setLayout(new BorderLayout());
 inicio=new PainelInicio(e,d,g);estudantesUI=new PainelEstudantes(e,g);disciplinasUI=new PainelDisciplinas(d,g);inscricoesUI=new PainelInscricoes(e,d,g);consultasUI=new PainelConsultas(e,d,g);
 conteudo.add(inicio,"Início");conteudo.add(estudantesUI,"Estudantes");conteudo.add(disciplinasUI,"Disciplinas");conteudo.add(inscricoesUI,"Inscrições");conteudo.add(consultasUI,"Consultas");add(criarMenu(),BorderLayout.WEST);add(conteudo,BorderLayout.CENTER);irPara("Início");}
 private JPanel criarMenu(){JPanel menu=new JPanel(new BorderLayout()){protected void paintComponent(Graphics g){Graphics2D d=(Graphics2D)g.create();d.setPaint(new GradientPaint(0,0,new Color(10,39,76),0,getHeight(),new Color(6,22,44)));d.fillRect(0,0,getWidth(),getHeight());d.dispose();super.paintComponent(g);}};menu.setOpaque(false);menu.setPreferredSize(new Dimension(226,0));menu.setBorder(new EmptyBorder(26,13,21,13));
 JPanel header=Estilo.clear(new BorderLayout(13,0));header.setBorder(new EmptyBorder(0,13,34,0));header.add(new JLabel(new Estilo.Glyph("cap",42,Color.WHITE)),BorderLayout.WEST);JPanel brand=Estilo.clear(new GridLayout(2,1));brand.add(Estilo.label("SGA",29,true,Color.WHITE));brand.add(Estilo.label("Gestão Académica",12,false,new Color(195,211,232)));header.add(brand);menu.add(header,BorderLayout.NORTH);
 JPanel tabs=Estilo.clear(new GridLayout(0,1,0,10));tabs.add(nav("Início","home"));tabs.add(nav("Estudantes","users"));tabs.add(nav("Disciplinas","book"));tabs.add(nav("Inscrições","clip"));tabs.add(nav("Consultas","search"));JPanel center=Estilo.clear(new BorderLayout());center.add(tabs,BorderLayout.NORTH);menu.add(center,BorderLayout.CENTER);
 JPanel bottom=Estilo.clear(new BorderLayout(0,12));JSeparator line=new JSeparator();line.setForeground(new Color(105,126,154));bottom.add(line,BorderLayout.NORTH);JButton exit=nav("Sair","exit");exit.addActionListener(e->{if(Estilo.yes(this,"Sair do sistema? Os dados não são guardados em ficheiro.")){new TelaBoasVindas().setVisible(true);dispose();}});bottom.add(exit);menu.add(bottom,BorderLayout.SOUTH);return menu;}
 private JButton nav(String name,String icon){JButton b=new JButton(name,new Estilo.Glyph(icon,22,Color.WHITE));b.setFont(Estilo.f(15,true));b.setForeground(Color.WHITE);b.setBackground(new Color(12,42,80));b.setBorder(new EmptyBorder(12,13,12,10));b.setHorizontalAlignment(SwingConstants.LEFT);b.setIconTextGap(14);b.setOpaque(true);b.setBorderPainted(false);b.setFocusPainted(false);b.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));if(!name.equals("Sair")){menuBotoes.put(name,b);b.addActionListener(e->irPara(name));}return b;}
 public void irPara(String name){switch(name){case "Início":inicio.actualizar();break;case "Estudantes":estudantesUI.actualizarTabela();break;case "Disciplinas":disciplinasUI.actualizarTabela();break;case "Inscrições":inscricoesUI.actualizarTabela();break;case "Consultas":consultasUI.actualizar();break;}cartas.show(conteudo,name);for(Map.Entry<String,JButton> e:menuBotoes.entrySet())e.getValue().setBackground(e.getKey().equals(name)?new Color(17,106,223):new Color(12,42,80));}
}
